  add('bush',{x:pk(r,[30,31]),y:45,c:pk(r,['#7c3aed','#dc2626','#f472b6'])},1);add('bush',{x:90,y:45,c:pk(r,['#7c3aed','#dc2626','#facc15'])},1);
