  const pv=shuf(r,['duck','duck','lily','lily','none']);
  [[46,72],[58,79],[70,70],[76,79.5]].forEach(([x,y],i)=>{let v=i===1?pk(r,['swan','boat','duck','lily']):pv[i];add('pond',{x,y,v,c:v==='boat'?pk(r,['#b45309','#2563eb','#dc2626']):pk(r,['#15803d','#a16207']),f:r()<0.5,fl:r()<0.6},5);});
  add('reeds',{x:34,y:71,n:ri(r,2,3)},5);add('reeds',{x:82,y:70,n:ri(r,2,3)},5);
