/* free spot finder: random points at least d away from all boxes */
function freeSpots(r,n,area,boxes,d=3,minGap=10){const out=[];for(let t=0;t<400&&out.length<n;t++){const x=area[0]+r()*area[2],y=area[1]+r()*area[3];
  if(boxes.some(b=>x>b[0]-d&&x<b[0]+b[2]+d&&y>b[1]-d&&y<b[1]+b[3]+d))continue;if(out.some(o=>Math.hypot(o[0]-x,o[1]-y)<minGap))continue;out.push([x,y]);}return out;}

